\begin{proof}
For any residue classes $\bar a,\bar b,\bar c\in\mathbb Z/n\mathbb Z$, using the definition of multiplication,
\[
\begin{aligned}
(\bar a\cdot\bar b)\cdot\bar c
&=\overline{ab}\cdot\bar c
=\overline{(ab)c}
=\overline{a(bc)}
=\bar a\cdot\overline{bc}
=\bar a\cdot(\bar b\cdot\bar c).
\end{aligned}
\]
The middle equality follows from associativity of integer multiplication. Hence multiplication in $\mathbb Z/n\mathbb Z$ is associative.
\end{proof}

\begin{proof}
Take arbitrary $\bar a,\bar b,\bar c\in\mathbb Z/n\mathbb Z$, represented by integers $a,b,c$. Then
\[
\begin{aligned}
(\bar a\cdot\bar b)\cdot\bar c
&=(\overline{ab})\cdot\bar c
=\overline{(ab)c}\\
&=\overline{a(bc)}
=\bar a\cdot\overline{bc}
=\bar a\cdot(\bar b\cdot\bar c).
\end{aligned}
\]
The third equality uses the associativity of multiplication in $\mathbb Z$. Hence, for all residue classes $\bar a,\bar b,\bar c$, we have $(\bar a\cdot\bar b)\cdot\bar c=\bar a\cdot(\bar b\cdot\bar c)$, proving associativity.
\end{proof}

\begin{proof}
Let $\bar a,\bar b,\bar c$ be arbitrary elements of $\mathbb Z/n\mathbb Z$, with representatives $a,b,c\in\mathbb Z$. The quotient multiplication is defined by $\bar x\cdot\bar y=\overline{xy}$. Consequently,
\[
\begin{aligned}
(\bar a\cdot\bar b)\cdot\bar c
&=\overline{ab}\cdot\bar c
=\overline{(ab)c}
=\overline{a(bc)}
=\bar a\cdot\overline{bc}
=\bar a\cdot(\bar b\cdot\bar c).
\end{aligned}
\]
The equality $(ab)c=a(bc)$ holds in $\mathbb Z$. Since the residue classes were arbitrary, multiplication on $\mathbb Z/n\mathbb Z$ is associative.
\end{proof}
